_cache = {}


def has(name):
    return name in PATHS


def svg(name, color="#5f6368"):
    d = PATHS.get(name, PATHS["more"])
    return ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="%s" d="%s"/></svg>' % (color, d)).encode("utf-8")


def pixmap(name, color="#5f6368", size=20, dpr=2.0):
    key = (name, str(color), int(size), dpr)
    if key in _cache:
        return _cache[key]
    from PyQt6.QtSvg import QSvgRenderer
    px = QPixmap(int(size * dpr), int(size * dpr)); px.fill(Qt.GlobalColor.transparent)
    r = QSvgRenderer(QByteArray(svg(name, QColor(color).name() if not isinstance(color, str) else color)))
    p = QPainter(px); p.setRenderHint(QPainter.RenderHint.Antialiasing); p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
    r.render(p, QRectF(0, 0, px.width(), px.height())); p.end()
    px.setDevicePixelRatio(dpr)
    if len(_cache) > 600:
        _cache.clear()
    _cache[key] = px
    return px


def icon(name, color="#5f6368", size=20):
    ic = QIcon()
    ic.addPixmap(pixmap(name, color, size), QIcon.Mode.Normal)
    ic.addPixmap(pixmap(name, color, size), QIcon.Mode.Active)
    try:
        c = QColor(color); c.setAlpha(110)
        ic.addPixmap(pixmap(name, c.name(QColor.NameFormat.HexArgb), size), QIcon.Mode.Disabled)
    except Exception:
        pass
    return ic
